package com.yuegang.zhihui.order.infrastructure;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.common.security.*;import com.yuegang.zhihui.inventory.api.*;import com.yuegang.zhihui.wallet.api.*;import java.time.*;import java.util.*;import org.springframework.web.client.*;
public final class CommerceReconciliationClient{private final RestClient wallet,inventory;private final InternalServiceSignature signatures;private final ObjectMapper json;public CommerceReconciliationClient(String walletBase,String inventoryBase,byte[]k,ObjectMapper j){wallet=RestClient.builder().baseUrl(walletBase).build();inventory=RestClient.builder().baseUrl(inventoryBase).build();signatures=new InternalServiceSignature(k,Clock.systemUTC(),Duration.ofSeconds(30));json=j;}public WalletReferenceView wallet(String reference){return get(wallet,"/internal/v1/wallet/references/"+reference,WalletReferenceView.class);}public InventoryReferenceView inventory(String reference){return get(inventory,"/internal/v1/inventory/references/"+reference,InventoryReferenceView.class);}@SuppressWarnings("unchecked")private<T>T get(RestClient client,String path,Class<T>type){Instant now=Instant.now();var m=new InternalServiceSignature.Metadata("ygh-order-service","GET",path,now);Map<String,Object>body=client.get().uri(path).header("X-YGH-Service","ygh-order-service").header("X-YGH-Service-Timestamp",Long.toString(now.toEpochMilli())).header("X-YGH-Service-Signature",signatures.sign(m)).retrieve().body(Map.class);if(body==null||body.get("data")==null)throw new IllegalStateException("reconciliation response missing");return json.convertValue(body.get("data"),type);}}
